import type { FixItem } from './analysis';

/** Lockfiles are generated by npm, so only hand-written manifests can be patched. */
export const canPatch = (fileName: string) => ['package.json', 'requirements.txt'].includes(fileName.toLowerCase());

const normalizePy = (name: string) => name.toLowerCase().replace(/[-_.]+/g, '-');

function patchPackageJson(text: string, items: FixItem[]): string {
  const data = JSON.parse(text);
  const indent = text.match(/^[ \t]+(?=")/m)?.[0] ?? '  ';
  const sections = ['dependencies', 'devDependencies', 'optionalDependencies'] as const;
  const overrides: Record<string, string> = { ...(data.overrides || {}) };
  let usedOverrides = false;

  for (const item of items) {
    const section = sections.find(s => data[s] && item.name in data[s]);
    if (section) {
      // Keep the author's range style (^, ~ or exact)
      const prefix = String(data[section][item.name]).match(/^[\^~]/)?.[0] ?? '';
      data[section][item.name] = `${prefix}${item.target}`;
    } else {
      // Transitive: npm's `overrides` forces the version wherever it appears in the tree
      overrides[item.name] = `^${item.target}`;
      usedOverrides = true;
    }
  }
  if (usedOverrides) data.overrides = overrides;
  return JSON.stringify(data, null, indent) + (text.endsWith('\n') ? '\n' : '');
}

function patchRequirements(text: string, items: FixItem[]): string {
  const pending = new Map(items.map(i => [normalizePy(i.name), i]));
  const lines = text.split(/\r?\n/).map(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('-')) return line;
    const m = line.match(/^(\s*)([A-Za-z0-9][A-Za-z0-9._-]*)(\[[^\]]*\])?\s*([^;#]*)(.*)$/);
    if (!m) return line;
    const item = pending.get(normalizePy(m[2]));
    if (!item) return line;
    pending.delete(normalizePy(m[2]));
    const op = m[4].trim().startsWith('==') ? '==' : '>=';
    const rest = m[5].trim();
    return `${m[1]}${m[2]}${m[3] ?? ''}${op}${item.target}${rest ? ` ${rest}` : ''}`;
  });

  if (pending.size) {
    while (lines.length && lines[lines.length - 1] === '') lines.pop();
    lines.push('', '# Transitive pins added by DepScan');
    for (const item of pending.values()) lines.push(`${item.name}>=${item.target}`);
    lines.push('');
  }
  return lines.join('\n');
}

export function patchManifest(fileName: string, text: string, items: FixItem[]): string {
  return fileName.toLowerCase() === 'package.json' ? patchPackageJson(text, items) : patchRequirements(text, items);
}
